#!/usr/bin/env python3
import argparse,json,re
from pathlib import Path
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--nodes',required=True);ap.add_argument('--authors',required=True);ap.add_argument('--works',required=True);ap.add_argument('--dblp',required=True);ap.add_argument('--output',required=True);a=ap.parse_args(); nodes=json.loads(Path(a.nodes).read_text()); authors=json.loads(Path(a.authors).read_text()); raw=json.loads(Path(a.works).read_text()); by={}
 for w in raw:
  key=(w.get('doi') or w.get('id') or re.sub(r'\W','',w.get('title','')).lower()); by[key]={'work_id':w.get('id'),'title':w.get('title'),'authors':[x.get('author',{}).get('display_name') for x in w.get('authorships',[])],'author_ids':[x.get('author',{}).get('id') for x in w.get('authorships',[])],'publication_year':w.get('publication_year'),'publication_date':w.get('publication_date'),'doi':w.get('doi'),'venue':(w.get('primary_location') or {}).get('source',{}).get('display_name'),'institutions':list({i.get('display_name') for x in w.get('authorships',[]) for i in x.get('institutions',[])}),'topics':w.get('topics',[]),'cited_by_count':w.get('cited_by_count',0),'referenced_works':w.get('referenced_works',[]),'open_access':w.get('open_access'),'sources':['openalex'],'match_confidence':'openalex-author'}
 out=Path(a.output); out.mkdir(parents=True,exist_ok=True); (out/'authors.json').write_text(json.dumps(authors,ensure_ascii=False,indent=2)); (out/'works.json').write_text(json.dumps(list(by.values()),ensure_ascii=False,indent=2)); (out/'nodes.json').write_text(json.dumps(nodes,ensure_ascii=False,indent=2)); (out/'edges.json').write_text(Path(Path(a.nodes).parent/'edges.json').read_text() if (Path(a.nodes).parent/'edges.json').exists() else '[]'); (out/'manifest.json').write_text(json.dumps({'sources':['AcademicTree','OpenAlex','DBLP'],'work_count':len(by),'dblp_status':list({x['status'] for x in json.loads(Path(a.dblp).read_text())})},ensure_ascii=False,indent=2))
if __name__=='__main__':main()
